-- PostgreSQL schema for AI Oral Exam Practice.
-- UUIDs are generated by PostgreSQL; gen_random_uuid() is built in on supported
-- PostgreSQL versions (13+). Apply this file to an empty database.
-- CREATE DATABASE ai_oral_exam_practice;

CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email TEXT NOT NULL,
    full_name TEXT NOT NULL,
    password_hash TEXT,
    avatar_url TEXT,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT users_email_not_blank CHECK (btrim(email) <> ''),
    CONSTRAINT users_full_name_not_blank CHECK (btrim(full_name) <> '')
);

CREATE UNIQUE INDEX users_email_lower_uq ON users (lower(email));

CREATE TABLE user_roles (
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    role TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role),
    CONSTRAINT user_roles_role_check CHECK (role IN ('student', 'instructor', 'admin'))
);

CREATE TABLE courses (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code TEXT NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    semester TEXT,
    department TEXT,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT courses_code_not_blank CHECK (btrim(code) <> ''),
    CONSTRAINT courses_name_not_blank CHECK (btrim(name) <> '')
);

CREATE TABLE course_enrollments (
    course_id UUID NOT NULL REFERENCES courses(id) ON DELETE RESTRICT,
    student_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    enrolled_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    status TEXT NOT NULL DEFAULT 'active',
    PRIMARY KEY (course_id, student_id),
    CONSTRAINT course_enrollments_status_check CHECK (status IN ('active', 'withdrawn', 'completed'))
);
CREATE INDEX course_enrollments_student_course_idx ON course_enrollments (student_id, course_id);

CREATE TABLE course_instructors (
    course_id UUID NOT NULL REFERENCES courses(id) ON DELETE RESTRICT,
    instructor_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (course_id, instructor_id)
);
CREATE INDEX course_instructors_instructor_course_idx ON course_instructors (instructor_id, course_id);

CREATE TABLE questions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    course_id UUID NOT NULL REFERENCES courses(id) ON DELETE RESTRICT,
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    topic TEXT,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX questions_course_active_idx ON questions (course_id, is_active);

CREATE TABLE question_versions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    question_id UUID NOT NULL REFERENCES questions(id) ON DELETE RESTRICT,
    version_no INTEGER NOT NULL,
    title TEXT NOT NULL,
    prompt TEXT NOT NULL,
    reference_answer TEXT,
    difficulty TEXT,
    time_limit_seconds INTEGER,
    tags TEXT[] NOT NULL DEFAULT '{}',
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT question_versions_version_positive CHECK (version_no > 0),
    CONSTRAINT question_versions_time_limit_positive CHECK (time_limit_seconds IS NULL OR time_limit_seconds > 0),
    CONSTRAINT question_versions_difficulty_check CHECK (difficulty IS NULL OR difficulty IN ('easy', 'medium', 'hard')),
    CONSTRAINT question_versions_question_version_uq UNIQUE (question_id, version_no),
    CONSTRAINT question_versions_id_question_uq UNIQUE (id, question_id)
);

CREATE TABLE rubric_versions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    question_version_id UUID NOT NULL REFERENCES question_versions(id) ON DELETE RESTRICT,
    version_no INTEGER NOT NULL,
    total_score NUMERIC(6,2) NOT NULL,
    grading_instructions TEXT,
    created_by UUID REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT rubric_versions_version_positive CHECK (version_no > 0),
    CONSTRAINT rubric_versions_total_score_positive CHECK (total_score > 0),
    CONSTRAINT rubric_versions_question_version_uq UNIQUE (question_version_id, version_no),
    CONSTRAINT rubric_versions_id_question_version_uq UNIQUE (id, question_version_id)
);

CREATE TABLE rubric_criteria (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    rubric_version_id UUID NOT NULL REFERENCES rubric_versions(id) ON DELETE RESTRICT,
    position INTEGER NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    max_score NUMERIC(6,2) NOT NULL,
    CONSTRAINT rubric_criteria_position_positive CHECK (position > 0),
    CONSTRAINT rubric_criteria_max_score_positive CHECK (max_score > 0),
    CONSTRAINT rubric_criteria_rubric_position_uq UNIQUE (rubric_version_id, position),
    CONSTRAINT rubric_criteria_id_rubric_uq UNIQUE (id, rubric_version_id)
);

CREATE TABLE practice_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    student_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    question_version_id UUID NOT NULL REFERENCES question_versions(id) ON DELETE RESTRICT,
    rubric_version_id UUID NOT NULL REFERENCES rubric_versions(id) ON DELETE RESTRICT,
    status TEXT NOT NULL DEFAULT 'draft',
    transcript_text TEXT,
    transcript_confirmed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at TIMESTAMPTZ,
    CONSTRAINT practice_sessions_status_check CHECK (status IN (
        'draft', 'recording', 'uploaded', 'transcribing', 'transcript_review',
        'grading', 'completed', 'transcription_failed', 'grading_failed', 'cancelled'
    )),
    CONSTRAINT practice_sessions_rubric_question_fk
        FOREIGN KEY (rubric_version_id, question_version_id)
        REFERENCES rubric_versions (id, question_version_id) ON DELETE RESTRICT,
    CONSTRAINT practice_sessions_id_rubric_uq UNIQUE (id, rubric_version_id)
);
CREATE INDEX practice_sessions_student_created_idx ON practice_sessions (student_id, created_at DESC);
CREATE INDEX practice_sessions_status_updated_idx ON practice_sessions (status, updated_at);

CREATE TABLE audio_assets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES practice_sessions(id) ON DELETE RESTRICT,
    object_key TEXT NOT NULL UNIQUE,
    mime_type TEXT NOT NULL,
    size_bytes BIGINT NOT NULL,
    duration_seconds NUMERIC(10,3),
    sha256 CHAR(64),
    uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at TIMESTAMPTZ,
    deleted_at TIMESTAMPTZ,
    CONSTRAINT audio_assets_size_nonnegative CHECK (size_bytes >= 0),
    CONSTRAINT audio_assets_duration_nonnegative CHECK (duration_seconds IS NULL OR duration_seconds >= 0),
    CONSTRAINT audio_assets_sha256_check CHECK (sha256 IS NULL OR sha256 ~ '^[0-9a-fA-F]{64}$'),
    CONSTRAINT audio_assets_id_session_uq UNIQUE (id, session_id)
);

CREATE TABLE transcription_runs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL REFERENCES practice_sessions(id) ON DELETE RESTRICT,
    audio_asset_id UUID NOT NULL,
    status TEXT NOT NULL,
    provider TEXT,
    model_version TEXT,
    language TEXT,
    raw_transcript TEXT,
    processing_ms INTEGER,
    error_code TEXT,
    started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at TIMESTAMPTZ,
    CONSTRAINT transcription_runs_status_check CHECK (status IN ('queued', 'running', 'succeeded', 'failed')),
    CONSTRAINT transcription_runs_processing_nonnegative CHECK (processing_ms IS NULL OR processing_ms >= 0),
    CONSTRAINT transcription_runs_audio_session_fk
        FOREIGN KEY (audio_asset_id, session_id)
        REFERENCES audio_assets (id, session_id) ON DELETE RESTRICT
);
CREATE INDEX transcription_runs_session_created_idx ON transcription_runs (session_id, started_at DESC);

CREATE TABLE evaluation_runs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL,
    rubric_version_id UUID NOT NULL REFERENCES rubric_versions(id) ON DELETE RESTRICT,
    status TEXT NOT NULL,
    provider TEXT,
    model_version TEXT,
    prompt_version TEXT,
    total_score NUMERIC(6,2),
    max_score NUMERIC(6,2),
    strengths JSONB,
    improvements JSONB,
    uncertainty_notes JSONB,
    needs_human_review BOOLEAN NOT NULL DEFAULT FALSE,
    processing_ms INTEGER,
    error_code TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at TIMESTAMPTZ,
    CONSTRAINT evaluation_runs_status_check CHECK (status IN ('queued', 'running', 'succeeded', 'failed')),
    CONSTRAINT evaluation_runs_processing_nonnegative CHECK (processing_ms IS NULL OR processing_ms >= 0),
    CONSTRAINT evaluation_runs_scores_nonnegative CHECK (
        (total_score IS NULL OR total_score >= 0) AND (max_score IS NULL OR max_score >= 0)
    ),
    CONSTRAINT evaluation_runs_score_within_max CHECK (
        total_score IS NULL OR max_score IS NULL OR total_score <= max_score
    ),
    CONSTRAINT evaluation_runs_session_rubric_fk
        FOREIGN KEY (session_id, rubric_version_id)
        REFERENCES practice_sessions (id, rubric_version_id) ON DELETE RESTRICT,
    CONSTRAINT evaluation_runs_id_rubric_uq UNIQUE (id, rubric_version_id)
);
CREATE INDEX evaluation_runs_session_created_idx ON evaluation_runs (session_id, created_at DESC);

CREATE TABLE evaluation_criterion_scores (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    evaluation_run_id UUID NOT NULL,
    rubric_version_id UUID NOT NULL,
    rubric_criterion_id UUID NOT NULL,
    score NUMERIC(6,2) NOT NULL,
    max_score NUMERIC(6,2) NOT NULL,
    evidence TEXT,
    feedback TEXT,
    missing_or_incorrect JSONB,
    CONSTRAINT evaluation_criterion_scores_score_range CHECK (score >= 0 AND score <= max_score),
    CONSTRAINT evaluation_criterion_scores_max_positive CHECK (max_score > 0),
    CONSTRAINT evaluation_criterion_scores_run_criterion_uq UNIQUE (evaluation_run_id, rubric_criterion_id),
    CONSTRAINT evaluation_criterion_scores_run_rubric_fk
        FOREIGN KEY (evaluation_run_id, rubric_version_id)
        REFERENCES evaluation_runs (id, rubric_version_id) ON DELETE RESTRICT,
    CONSTRAINT evaluation_criterion_scores_criterion_rubric_fk
        FOREIGN KEY (rubric_criterion_id, rubric_version_id)
        REFERENCES rubric_criteria (id, rubric_version_id) ON DELETE RESTRICT
);
CREATE INDEX evaluation_criterion_scores_criterion_idx ON evaluation_criterion_scores (rubric_criterion_id);

CREATE TABLE human_reviews (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID NOT NULL,
    reviewer_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    rubric_version_id UUID NOT NULL REFERENCES rubric_versions(id) ON DELETE RESTRICT,
    total_score NUMERIC(6,2) NOT NULL,
    notes TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT human_reviews_total_score_nonnegative CHECK (total_score >= 0),
    CONSTRAINT human_reviews_session_rubric_fk
        FOREIGN KEY (session_id, rubric_version_id)
        REFERENCES practice_sessions (id, rubric_version_id) ON DELETE RESTRICT,
    CONSTRAINT human_reviews_id_rubric_uq UNIQUE (id, rubric_version_id)
);

CREATE TABLE human_review_criterion_scores (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    human_review_id UUID NOT NULL,
    rubric_version_id UUID NOT NULL,
    rubric_criterion_id UUID NOT NULL,
    score NUMERIC(6,2) NOT NULL,
    comment TEXT,
    CONSTRAINT human_review_criterion_scores_score_range CHECK (score >= 0),
    CONSTRAINT human_review_criterion_scores_review_criterion_uq UNIQUE (human_review_id, rubric_criterion_id),
    CONSTRAINT human_review_criterion_scores_review_rubric_fk
        FOREIGN KEY (human_review_id, rubric_version_id)
        REFERENCES human_reviews (id, rubric_version_id) ON DELETE RESTRICT,
    CONSTRAINT human_review_criterion_scores_criterion_rubric_fk
        FOREIGN KEY (rubric_criterion_id, rubric_version_id)
        REFERENCES rubric_criteria (id, rubric_version_id) ON DELETE RESTRICT
);
CREATE INDEX human_review_criterion_scores_criterion_idx ON human_review_criterion_scores (rubric_criterion_id);

CREATE TABLE research_consents (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    purpose TEXT NOT NULL,
    consent_version TEXT NOT NULL,
    status TEXT NOT NULL,
    granted_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT research_consents_status_check CHECK (status IN ('granted', 'revoked', 'declined')),
    CONSTRAINT research_consents_timestamps_check CHECK (
        (status = 'granted' AND granted_at IS NOT NULL AND revoked_at IS NULL)
        OR (status = 'revoked' AND granted_at IS NOT NULL AND revoked_at IS NOT NULL)
        OR (status = 'declined' AND revoked_at IS NULL)
    )
);
CREATE INDEX research_consents_user_created_idx ON research_consents (user_id, created_at DESC);
